package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonRetiredException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The paste box: lines of name,amount,date,note (the note may hold commas and may be absent; a blank date
 * takes the sheet's entry date, its today when off), each a DRAFT claim for the person on the sheet with
 * the name or an alias (ignoring case), added in order. A note ending in " #<reference>" gives the claim that external
 * reference, which is not part of the note. Blank lines are skipped. One change: every line is checked
 * with the claim form's rules (a reference used twice in the paste too, ignoring case), and a refused line
 * refuses the paste, adding nothing and writing nothing.
 */
@Service
public class PasteService {

    private static final Pattern AMOUNT = Pattern.compile("-?\\d{1,13}(\\.\\d{1,2})?");
    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);

    private final PersonRepository people;
    private final ClaimService claims;

    public PasteService(PersonRepository people, ClaimService claims) {
        this.people = people;
        this.claims = claims;
    }

    private record Line(int number, Person person, BigDecimal amount, LocalDate date, String note,
            String ref) {
    }

    /** The claims added, in the order of their lines. */
    @Transactional
    public List<Claim> paste(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        String[] raw = text == null ? new String[0] : text.split("\\r?\\n");
        for (int i = 0; i < raw.length; i++) {
            if (!raw[i].isBlank()) {
                Line line = parse(sheetId, i + 1, raw[i]);
                if (line.ref() != null && !refs.add(line.ref().toLowerCase(Locale.ROOT))) {
                    throw refused(line.number(), "the reference " + line.ref() + " is already in this paste.");
                }
                lines.add(line);
            }
        }
        if (lines.isEmpty()) {
            throw new ClaimPasteException("Paste at least one line of name,amount,date,note.");
        }
        List<Claim> added = new ArrayList<>();
        for (Line line : lines) {
            try {
                added.add(claims.add(sheetId, user, line.person().getId(), line.amount(), line.date(), line.note(),
                        null, line.ref(), List.of()));
            } catch (PeriodClosedException | PersonRetiredException | ClaimCorrectionException
                    | ClaimRefException e) {
                throw new ClaimPasteException("Line " + line.number() + ": " + e.getMessage());
            }
        }
        return added;
    }

    private Line parse(String sheetId, int number, String raw) {
        String[] f = raw.split(",", 4);
        String name = f[0].trim();
        if (name.isEmpty() || name.length() > 200) {
            throw refused(number, "enter a name.");
        }
        Person person = people.findByNameOrAlias(sheetId, name)
                .orElseThrow(() -> refused(number, "no one on the sheet is named " + name + "."));
        String amount = f.length > 1 ? f[1].trim() : "";
        if (!AMOUNT.matcher(amount).matches()) {
            throw refused(number, "enter an amount with up to two decimals.");
        }
        String date = f.length > 2 ? f[2].trim() : "";
        LocalDate on = null;
        if (!date.isEmpty()) {
            try {
                on = LocalDate.parse(date, DATE);
            } catch (DateTimeParseException e) {
                throw refused(number, "enter a date as YYYY-MM-DD.");
            }
        }
        String note = f.length > 3 ? f[3].trim() : "";
        String ref = null;
        int hash = note.lastIndexOf(" #");
        if (hash >= 0 && !note.substring(hash + 2).isBlank()) {
            ref = note.substring(hash + 2).trim();
            note = note.substring(0, hash).trim();
        }
        if (note.length() > 1000) {
            throw refused(number, "the note is too long.");
        }
        if (ref != null && ref.length() > 200) {
            throw refused(number, "the reference is too long.");
        }
        return new Line(number, person, new BigDecimal(amount), on, note, ref);
    }

    private static ClaimPasteException refused(int number, String why) {
        return new ClaimPasteException("Line " + number + ": " + why);
    }
}
            : [...ps, added.person],
        );
        this.claims.update((cs) => [added.claim, ...cs]);
      }
      return null;
    } catch (e) {
      return failed('add', e);
    }
  }

  /** Add a DRAFT claim for each pasted line of name,amount,date,note, in order, for the person on the
   *  sheet with the name; how many were added, or an error message when any line is refused (then the
   *  server adds none). */
  async paste(text: string): Promise<number | string> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    if (!text.trim()) return 'Paste at least one line of name,amount,date,note.';
    try {
      const done = await firstValueFrom(
        this.http.post<{ added: number; claims: Claim[] }>(
          `${this.url(sid)}/claims/paste`,
          { text },
          { headers: { 'X-User': user } },
        ),
      );
      if (this.session.sheetId() === sid) this.claims.update((cs) => [...[...done.claims].reverse(), ...cs]);
      return done.added;
    } catch (e) {
      return failed('add', e).replace(' claim', ' claims');
    }
  }

  /** Change a DRAFT claim's amount, date and note; when refused, the reason and whether it is the
   *  claim itself that refused it (it is no longer a DRAFT) rather than the fields typed. */
  async update(id: number, f: ClaimFields): Promise<{ message: string; onClaim: boolean } | null> {
    const refused = this.check(f);
    if (refused) return { message: refused, onClaim: false };
    const sid = this.session.sheetId()!;
    try {
      const claim = await firstValueFrom(
        this.http.put<Claim>(`${this.url(sid)}/claims/${id}`, this.body(f), {
          headers: { 'X-User': this.session.user()! },
        }),
      );
      if (this.session.sheetId() === sid) {
        // a tag the edit took off stays among those used on the sheet
        const was = this.claims().find((c) => c.id === id)?.tags ?? [];
        this.storedTags.update((ts) => [...new Set([...ts, ...was])]);
        this.claims.update((cs) => cs.map((c) => (c.id === id ? claim : c)));
      }
import { Component, inject, signal } from '@angular/core';
import { Claims } from '../../core/claims';

// A paste box of name,amount,date,note lines, each a DRAFT claim for the named person; reports how many
// were added, or why the paste was refused (then nothing is added).
@Component({
  selector: 'app-paste-claims',
  template: `
    <form (submit)="paste($event)" aria-label="Paste claims">
      <label for="paste-claims">Paste claims (one per line: name,amount,date,note, the note ending in " #reference" to give one)</label>
      <textarea
        id="paste-claims"
        data-testid="paste-claims"
        rows="4"
        [value]="text()"
        (input)="text.set(value($event)); error.set(null)"
      ></textarea>
      <button type="submit" data-testid="paste-submit" [disabled]="running()">Add pasted claims</button>
      @if (added() !== null) {
        <p>Added <span data-testid="paste-added">{{ added() }}</span></p>
      }
      @if (error(); as err) {
        <p role="alert" data-testid="paste-error">{{ err }}</p>
      }
    </form>
  `,
})
export class PasteClaims {
  private readonly claims = inject(Claims);
  protected readonly text = signal('');
  protected readonly running = signal(false);
  protected readonly added = signal<number | null>(null);
  protected readonly error = signal<string | null>(null);

  protected async paste(e: Event): Promise<void> {
    e.preventDefault();
    if (this.running()) return; // a second submit before the first has answered
    this.added.set(null);
    this.error.set(null);
    this.running.set(true);
    try {
      const done = await this.claims.paste(this.text());
      if (typeof done === 'string') this.error.set(done);
      else {
        this.added.set(done);
        this.text.set('');
      }
    } finally {
      this.running.set(false);
    }
  }

  protected value(e: Event): string {
    return (e.target as HTMLTextAreaElement).value;
  }
}

